document.querySelectorAll('#creative-design-samples video').forEach(function (video) {
  video.addEventListener('loadeddata', function () {
    if (video.dataset.thumbnailReady) return;
    video.dataset.thumbnailReady = 'true';
    const captureTime = Math.min(Math.max(video.duration * 0.2, 0.5), 2.5);
    const drawThumbnail = function () {
      const canvas = document.createElement('canvas');
      canvas.width = 540;
      canvas.height = 960;
      const context = canvas.getContext('2d');
      const scale = Math.max(canvas.width / video.videoWidth, canvas.height / video.videoHeight);
      const width = video.videoWidth * scale;
      const height = video.videoHeight * scale;
      context.fillStyle = '#171717';
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(video, (canvas.width - width) / 2, (canvas.height - height) / 2, width, height);
      video.poster = canvas.toDataURL('image/jpeg', 0.86);
      video.removeEventListener('seeked', drawThumbnail);
    };
    video.addEventListener('seeked', drawThumbnail, { once: true });
    video.currentTime = captureTime;
  }, { once: true });
});
